import os
import tomllib
from typing import Any, Optional


class EnvCfgError(Exception):
    """Raised when a configuration value cannot be coerced or an env key has no default."""

    def __init__(self, key: str, expected: str, actual: Optional[str] = None):
        self.key = key
        self.expected = expected
        self.actual = actual
        msg = f"{key}: expected {expected}"
        if actual is not None:
            msg += f", got {actual!r}"
        super().__init__(msg)


def _coerce(value: str, expected: type) -> Any:
    """Coerce a string to the expected type, raising EnvCfgError on failure."""
    if expected is int:
        try:
            return int(value)
        except ValueError:
            raise EnvCfgError(value, "int")
    if expected is float:
        try:
            return float(value)
        except ValueError:
            raise EnvCfgError(value, "float")
    if expected is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise EnvCfgError(value, "bool")
    if expected is str:
        return value
    raise EnvCfgError(value, repr(expected))


