import os
import tempfile
from pathlib import Path

import pytest

from envcfg import EnvCfgError, load, _merge


def test_defaults_only():
    cfg = load({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_defaults_below_toml():
    defaults = {"a": 1, "b": 2}
    toml = {"a": 10, "c": 3}
    cfg = load(defaults, toml_path="/dev/null")  # missing file is skipped
    cfg = _merge(cfg, toml)
    assert cfg == {"a": 10, "b": 2, "c": 3}


def test_defaults_below_env():
    defaults = {"a": 1, "b": 2}
    env = {"APP__A": "10", "APP__C": "3"}
    cfg = load(defaults, env=env)
    assert cfg == {"a": 10, "b": 2, "c": "3"}


def test_toml_below_env():
    defaults = {"a": 1, "b": 2}
    toml = {"a": 10, "c": 3}
    env = {"APP__A": "100", "APP__C": "300"}
    cfg = load(defaults, toml_path="/dev/null", env=env)
    cfg = _merge(cfg, toml)
    cfg = load(cfg, env=env)
    assert cfg == {"a": 100, "b": 2, "c": 300}


def test_nested_defaults():
    cfg = load({"server": {"port": 80, "host": "localhost"}})
    assert cfg == {"server": {"port": 80, "host": "localhost"}}


def test_nested_toml():
    defaults = {"server": {"port": 80, "host": "localhost"}}
    toml = {"server": {"port": 8080, "ssl": True}}
    cfg = load(defaults, toml_path="/dev/null")
    cfg = _merge(cfg, toml)
    assert cfg == {"server": {"port": 8080, "host": "localhost", "ssl": True}}


def test_nested_env():
    defaults = {"server": {"port": 80, "host": "localhost"}}
    env = {"APP__SERVER__PORT": "3000", "APP__SERVER__SSL": "true"}
    cfg = load(defaults, env=env)
    assert cfg == {"server": {"port": 3000, "host": "localhost", "ssl": True}}


def test_int_coercion():
    cfg = load({"a": 1}, env={"APP__A": "42"})
    assert cfg == {"a": 42}


def test_float_coercion():
    cfg = load({"a": 1.0}, env={"APP__A": "3.14"})
    assert cfg == {"a": 3.14}


def test_bool_coercion_true():
    cfg = load({"a": False}, env={"APP__A": "true"})
    assert cfg == {"a": True}


